class AuthInterceptor @Inject constructor(private val tokens: TokenStore) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val req = chain.request().newBuilder()
            .header("Authorization", "Bearer ${tokens.access()}")
            .header("X-App-Version", BuildConfig.VERSION_NAME)
            .build()
        return chain.proceed(req)
    }
}

class TimingInterceptor : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val start = System.nanoTime()
        val response = chain.proceed(chain.request())
        val ms = (System.nanoTime() - start) / 1_000_000
        Log.d("HTTP", "${chain.request().url.encodedPath} took ${ms}ms (${response.code})")
        return response
    }
}

class TokenAuthenticator @Inject constructor(
    private val store: TokenStore,
    private val authApi: AuthApi
) : Authenticator {
    override fun authenticate(route: Route?, response: Response): Request? {
        if (response.priorResponse != null) return null          // already retried once
        synchronized(this) {
            val sent = response.request.header("Authorization")?.removePrefix("Bearer ")
            val current = store.access()
            val token = if (current != sent) current                // another thread refreshed
                        else authApi.refreshBlocking(store.refresh())?.also(store::save)?.access
                             ?: return null.also { store.clear() } // refresh failed: log out
            return response.request.newBuilder().header("Authorization", "Bearer $token").build()
        }
    }
}

override fun authenticate(route: Route?, response: Response): Request? {
    if (responseCount(response) >= 2) return null             // stop endless loops
    val usedToken = response.request.header("Authorization")?.substringAfter("Bearer ")
    synchronized(lock) {
        val latest = tokenStore.accessToken()
        val fresh = if (latest != null && latest != usedToken) latest     // someone already refreshed
                    else refreshBlocking() ?: run { tokenStore.clear(); return null }
        return response.request.newBuilder().header("Authorization", "Bearer $fresh").build()
    }
}

sealed interface NetResult<out T> {
    data class Ok<T>(val value: T) : NetResult<T>
    data class Http(val code: Int, val body: String?) : NetResult<Nothing>
    data class Network(val cause: IOException) : NetResult<Nothing>
}

suspend fun <T> safeCall(block: suspend () -> T): NetResult<T> = try {
    NetResult.Ok(block())
} catch (e: HttpException) {
    NetResult.Http(e.code(), e.response()?.errorBody()?.string())
} catch (e: IOException) {
    NetResult.Network(e)
}   // CancellationException is not caught, so cancellation still works

suspend fun <T> retryIO(times: Int = 3, first: Long = 500, block: suspend () -> T): T {
    var wait = first
    repeat(times - 1) {
        try { return block() } catch (e: IOException) { /* fall through and retry */ }
        delay(wait + Random.nextLong(0, wait / 2))      // backoff + jitter
        wait *= 2
    }
    return block()                                      // last try: let errors escape
}

