suspend fun like(postId: String) {
    db.withTransaction {
        db.posts().setLiked(postId, liked = true)              // UI updates instantly
        db.outbox().insert(OutboxOp(id = uuid(), type = "like", target = postId))
    }
    SyncWorker.enqueue(context)                                // sends when online
}
